add_exam_question(2007, "北京卷", "计算题", "质量m=1kg的小球从高h=5m处自由下落，落到地面后反弹，反弹后上升的最大高度为3.2m。求：（1）小球落地时的速度大小；（2）碰撞过程中动量的变化量。（g取10m/s²）",
    [], "（1）10m/s；（2）18kg·m/s，方向向上", "（1）v=√(2gh)=10m/s；（2）反弹速度8m/s，Δp=1×8-1×(-10)=18kg·m/s。")
