add_exam_question(2019, "天津卷", "选择题", "一个质量为m的物体放在光滑水平面上，受到水平恒力F作用，经过时间t后，物体的动量变化为（）",
    ["A. Ft", "B. Ft/m", "C. F/mt", "D. mFt"], "A", "根据动量定理，Δp=Ft。")
