add_exam_question(2021, "全国乙卷", "计算题", "质量M=4kg的木板静止在光滑水平面上，长度L=2m。质量m=1kg的物块放在木板右端，动摩擦因数μ=0.2。对物块施加F=6N水平力，求：（1）物块和木板的加速度；（2）物块滑离木板的时间。",
    [], "（1）a物=4m/s²，a板=0.5m/s²；（2）t=√(8/7)s", "（1）a物=(6-2)/1=4m/s²，a板=2/4=0.5m/s²；（2）L=0.5(a物-a板)t²→t=√(8/7)s。")
add_exam_question(2021, "全国乙卷", "计算题", "质量m=2kg的小球用长L=1m的轻绳悬挂，拉至与竖直方向成60°角释放，求：（1）最低点速度；（2）最低点绳子拉力。",
    [], "（1）√10 m/s；（2）60N", "（1）mgh=0.5mv²→v=√(2gh)=√10 m/s；（2）T-mg=mv²/L→T=60N。")

